-- tools/witch_sisters.py -> 2026_10_01_00_devourer_witch_sisters.sql).
DELETE FROM `trainer` WHERE `Id` = 9101200;
DELETE FROM `trainer_spell` WHERE `TrainerId` = 9101200;
